                client, recorder, 'a05-restart-record',
                title=f'A05 重启记录 {uuid.uuid4().hex[:8]}',
                description=f'A05 重启描述 {uuid.uuid4().hex[:8]}',
            )
            if target_id and record_id:
                doc = _home_page(
