def _check_category_state(client, recorder, prefix, expectations):
    categories = _fetch_categories(
        client, recorder, f'{prefix}-api-categories'
    )
    for label, name, category_id, expected_ids in expectations:
        item = _find_category_by_id(categories, category_id)
        if not isinstance(item, dict):
            item = _find_category_by_name(categories, name)
        count = item.get('count') if isinstance(item, dict) else None
        recorder.check(
            f'{prefix}-api-count-{label}',
            count == len(expected_ids),
            f'归类 {name!r} API count={count!r}（期望活动记录数 {len(expected_ids)}）',
        )
        listed = _fetch_bookmarks(
            client, recorder, f'{prefix}-api-list-{label}',
            params={'category': name},
        )
        actual_ids = _record_ids(listed)
        recorder.check(
            f'{prefix}-api-list-{label}',
            actual_ids == set(expected_ids),
            f'归类 {name!r} API 列表={sorted(actual_ids)}（期望 {sorted(set(expected_ids))}）',
        )

    home_doc = _home_page(client, recorder, f'{prefix}-html-home')
    home_counts = _category_count_values(home_doc)
    for label, name, category_id, expected_ids in expectations:
        values = home_counts.get(category_id, [])
        recorder.check(
            f'{prefix}-html-home-count-{label}',
            bool(values) and all(value == len(expected_ids) for value in values),
            f'归类 {name!r} 首页 HTML 计数={values!r}（期望 {len(expected_ids)}）',
        )

    categories_doc = _categories_page(
        client, recorder, f'{prefix}-html-categories'
    )
    categories_counts = _category_count_values(categories_doc)
    for label, name, category_id, expected_ids in expectations:
        values = categories_counts.get(category_id, [])
        recorder.check(
            f'{prefix}-html-categories-count-{label}',
            bool(values) and all(value == len(expected_ids) for value in values),
            f'归类 {name!r} /categories HTML 计数={values!r}（期望 {len(expected_ids)}）',
        )

    for label, name, category_id, expected_ids in expectations:
        filtered_doc = _home_page(
            client, recorder, f'{prefix}-html-filtered-{label}',
            params={'category': name},
        )
        actual_ids = _row_ids(filtered_doc)
        recorder.check(
            f'{prefix}-html-rows-{label}',
            actual_ids == set(expected_ids),
            f'归类 {name!r} HTML 记录行={sorted(actual_ids)}（期望 {sorted(set(expected_ids))}）',
        )


